package com.shopsphere.service; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.entity.*; import com.shopsphere.exception.ApiException; import com.shopsphere.repository.*; import com.shopsphere.security.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*; @Service public class ReviewService {private final ReviewRepository reviews;private final ProductRepository products;private final CurrentUser current;public ReviewService(ReviewRepository r,ProductRepository p,CurrentUser c){reviews=r;products=p;current=c;} public List<ReviewResponse> all(UUID pid){Product p=products.findById(pid).orElseThrow();return reviews.findAllByProduct(p).stream().map(x->new ReviewResponse(x.getId(),x.getUser().getName(),x.getRating(),x.getComment(),x.getCreatedAt())).toList();} public ReviewResponse add(UUID pid,ReviewRequest r,Authentication a){User u=current.get(a);Product p=products.findById(pid).orElseThrow();if(reviews.existsByUserAndProduct(u,p))throw new ApiException("REVIEW_EXISTS","You already reviewed this product");Review x=new Review();x.setUser(u);x.setProduct(p);x.setRating(r.rating());x.setComment(r.comment());reviews.save(x);return new ReviewResponse(x.getId(),u.getName(),x.getRating(),x.getComment(),x.getCreatedAt());}}
